"""Calculate the cumulative gain based on the rank list and return a list."""
def cumulative_gain(rank_list: Any) -> object {
    cumulative_set = [];
    cumulative_set.append(rank_list[0]);
    for i in range(1, len(rank_list)) {
        cg = cumulative_set[(i - 1)] + rank_list[i];
        cumulative_set.append(cg);
    }
    return cumulative_set;
}

"""Computes the Exact score (accuracy) of the predictions.

    Exact score is defined as the percentage of predictions that match at least
    one of the targets.

    Args:
        predictions: List of predictions.
        target_lists: List of targets (1 or more per prediction).

    Returns:
        Exact score between [0, 1].
    """
def compute_exact_score(predictions: Any, target_lists: Any) -> object {
    num_matches = sum(
        `any((pred == target) for target in targets)
        for (pred, targets) in zip(predictions, target_lists)
    );
    return (num_matches / max(len(predictions), 0.1));
}

"""Convert a list of instructions into an easm op code string.

    :param instruction_list:
    :return:
    """
def instruction_list_to_easm(instruction_list: list) -> str {
    result = "";
    for instruction in instruction_list {
        result += "{} {}".format(instruction["address"], instruction["opcode"]);
        if ("argument" in instruction) {
            result += " " + instruction["argument"];
        }
        result += "\n";
    }
    return result;
}

